#define REG_COUNT 8
int R[REG_COUNT];
unsigned char M[256];
int PC = 0; // Program Counter

enum { HALT = 0, LOAD = 1, ADD = 2 };

void cpu_step() {
    unsigned char op = M[PC++]; // Fetch Instruction
    int A = M[PC++];           // Operand 1
    int B = M[PC++];           // Operand 2 (Immediate)

    switch (op) {              // Decode & Execute
        case LOAD: R[A] = B; break;
        case ADD:  R[0] += R[1]; break;
        case HALT: PC = -1; break; // Signal stop
    }
}
